"""Cross-language check: a launcher generated by bin/new-claude.sh parses in Python.

The launcher is only built, never run.
"""

import os
import subprocess
from pathlib import Path

from claude_instances.launchers import discover_launchers

REPO = Path(__file__).resolve().parent.parent
NEW_CLAUDE = REPO / "bin/new-claude.sh"


def test_generated_launcher_has_argless_rule(tmp_path):
    fake_app = tmp_path / "FakeClaude.app"
    (fake_app / "Contents").mkdir(parents=True)
    (fake_app / "Contents/Info.plist").write_text(
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<plist version="1.0"><dict>'
        "<key>CFBundleExecutable</key><string>stubclaude</string>"
        "</dict></plist>\n"
    )
    support = Path.home() / "Library/Application Support"
    env = {**os.environ, "CLAUDE_LAUNCHER_DEFAULT_DATA_DIR": str(support / "claude-gen-test")}
    subprocess.run(
        [str(NEW_CLAUDE), "Claude GenTest", "--apps", str(tmp_path / "Apps"),
         "--claude-app", str(fake_app), "--dir", "claude-gen-test"],
        env=env, check=True, capture_output=True,
    )

    (launcher,) = discover_launchers([tmp_path / "Apps"])
    assert launcher.is_watchdog
    assert launcher.has_argless_rule
    assert launcher.data_dir == support / "claude-gen-test"
    assert launcher.claude_app == fake_app
